{"command": "cat > /prediction.json << 'EOF'
{
    "vllm/lora/ops/triton_ops/fused_moe_lora_op.py": {
        "_fused_moe_lora_kernel": "@triton.jit\ndef _fused_moe_lora_kernel(\n    a_ptr,\n    b_ptr,\n    c_ptr,\n    topk_weights_ptr,\n    sorted_token_ids_ptr,\n    expert_ids_ptr,\n    num_tokens_post_padded_ptr,\n    # Matrix dimensions\n    N,\n    K,\n    EM,\n    num_valid_tokens,\n    num_experts,\n    # The stride variables represent how much to increase the ptr by when\n    # moving by 1 element in a particular dimension. E.g. `stride_am` is\n    # how much to increase `a_ptr` by to get the element one row down\n    # (A has M rows).\n    stride_am,\n    stride_ak,\n    stride_bl,\n    stride_be,\n    stride_bk,\n    stride_bn,\n    stride_cm,\n    stride_cn,\n    stride_tl,\n    stride_el,\n    # Meta-parameters\n    num_slice_a: tl.constexpr,\n    num_slice_c: tl.constexpr,\n    slice_a_size: tl.constexpr,\n    slice_c_size: tl.constexpr,\n    top_k: tl.constexpr,\n    MUL_ROUTED_WEIGHT: tl.constexpr,\n    BLOCK_SIZE_M: tl.constexpr,\n    BLOCK_SIZE_N: tl.constexpr,\n    BLOCK_SIZE_K: tl.constexpr,\n    GROUP_SIZE_M: tl.constexpr,\n    SPLIT_K: tl.constexpr,\n):\n    # Get program IDs\n    pid = tl.program_id(axis=0)\n    slice_id = tl.program_id(axis=1)\n    lora_idx = tl.program_id(axis=2)\n    max_loras = tl.num_programs(axis=2)\n    \n    # Calculate number of program IDs for M and N dimensions\n    num_pid_m = tl.cdiv(EM, BLOCK_SIZE_M)\n    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)\n    \n    # Extract split-K program ID and M/N program ID\n    # pid = pid_sk + SPLIT_K * pid_mn\n    pid_sk = pid % SPLIT_K\n    pid_mn = pid // SPLIT_K\n    \n    # Calculate pid_m and pid_n from pid_mn (same as original logic)\n    num_pid_in_group = GROUP_SIZE_M * num_pid_n\n    group_id = pid_mn // num_pid_in_group\n    first_pid_m = group_id * GROUP_SIZE_M\n    group_size_m = min(num_pid_m - first_pid_m, GROUP_SIZE_M)\n    pid_m = first_pid_m + ((pid_mn % num_pid_in_group) % group_size_m)\n    pid_n = (pid_mn % num_pid_in_group) // group_size_m\n\n    # Early exit if this program is beyond valid tokens\n    num_tokens_post_padded = tl.load(num_tokens_post_padded_ptr + lora_idx)\n    if pid_m * BLOCK_SIZE_M >= num_tokens_post_padded:\n        return\n\n    # Get the expert_id to process current shard\n    ind = lora_idx * stride_el + pid_m\n    expert_id = tl.load(expert_ids_ptr + ind)\n    if expert_id == -1:\n        return\n\n    # Get pointers for current slice\n    cur_a_ptr = a_ptr + (slice_id % num_slice_a) * slice_a_size\n    cur_b_ptr = tl.load(b_ptr + slice_id).to(tl.pointer_type(tl.bfloat16))\n    cur_c_ptr = c_ptr + (slice_id % num_slice_c) * slice_c_size\n\n    # Calculate offsets for N dimension\n    offs_bn = (pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N).to(tl.int64)) % N\n    offs_k = tl.arange(0, BLOCK_SIZE_K)\n    \n    # Calculate starting K offset for this split-K slice\n    k_start = pid_sk * BLOCK_SIZE_K\n    \n    # Early exit if k_start is beyond K dimension\n    if k_start >= K:\n        return\n\n    # Get token information\n    offs_token_id = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M).to(tl.int64)\n    token_ind = stride_tl * lora_idx + offs_token_id\n    offs_token = tl.load(\n        sorted_token_ids_ptr + token_ind, token_ind < max_loras * stride_tl, 0.0\n    )\n    token_mask = offs_token < num_valid_tokens\n\n    # Initialize pointers with split-K offset\n    a_ptrs = cur_a_ptr + (\n        offs_token[:, None] // top_k * stride_am + \n        (k_start + offs_k[None, :]) * stride_ak\n    )\n\n    b_ptrs = (\n        cur_b_ptr\n        + lora_idx * stride_bl\n        + expert_id * stride_be\n        + ((k_start + offs_k[:, None]) * stride_bk + offs_bn[None, :] * stride_bn)\n    )\n\n    # Accumulator for partial results\n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)\n    \n    # Iterate over K dimension with split-K stride\n    # Each program processes every SPLIT_K-th block starting from k_start\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K * SPLIT_K)):\n        k_offset = k * (BLOCK_SIZE_K * SPLIT_K)\n        current_k_start = k_start + k_offset\n        \n        # Check if we're still within K dimension\n        if current_k_start < K:\n            # Load A block with masking\n            a = tl.load(\n                a_ptrs,\n                mask=token_mask[:, None] & ((current_k_start + offs_k[None, :]) < K),\n                other=0.0,\n            )\n            # Load B block with masking\n            b = tl.load(\n                b_ptrs, \n                mask=(current_k_start + offs_k[:, None]) < K, \n                other=0.0\n            )\n            # Accumulate dot product\n            accumulator += tl.dot(a, b)\n            \n            # Advance pointers to next block for this split-K slice\n            a_ptrs += BLOCK_SIZE_K * SPLIT_K * stride_ak\n            b_ptrs += BLOCK_SIZE_K * SPLIT_K * stride_bk\n\n    # Apply MoE routing weight if needed\n    if MUL_ROUTED_WEIGHT:\n        moe_weight = tl.load(topk_weights_ptr + offs_token, mask=token_mask, other=0)\n        accumulator = accumulator * moe_weight[:, None]\n\n    # Convert to output dtype\n    accumulator = accumulator.to(tl.bfloat16)\n    \n    # Prepare output pointers\n    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    c_ptrs = cur_c_ptr + stride_cm * offs_token[:, None] + stride_cn * offs_cn[None, :]\n    c_mask = token_mask[:, None] & (offs_cn[None, :] < N)\n    \n    # Write back results\n    if SPLIT_K == 1:\n        # Normal store when not using split-K\n        tl.store(c_ptrs, accumulator, mask=c_mask)\n    else:\n        # Atomic accumulation for split-K parallelism\n        tl.atomic_add(c_ptrs, accumulator, mask=c_mask)\n"
    }
}
EOF"}

